const D = { energy: .62, scale: 1, speed: 1, density: .5, spread: .55, cells: .6, hue: 196, x: .5, y: .5, style: 'shallow_water', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- KP-II line-soliton web, the EXACT (2,N-2)-soliton solution (Kodama / Grassmannian):
//        tau = sum over i<j of  (t_j - t_i)(k_j - k_i) * exp(theta_i + theta_j)
//        theta_i = k_i x + k_i^2 y + k_i^3 t
//        u = 2 * d2/dx2 log(tau)
// A totally-positive 2xN Vandermonde matrix guarantees tau > 0, so the solution is regular
// everywhere. Solitary waves ride the seams where two exponentials balance; they meet at
// resonant Y- and X-junctions, cross, and emerge intact with only a phase shift. ----
const BW = Math.max(360, Math.min(720, Math.round(width / 2.4))), BH = Math.max(64, Math.round(BW * height / width));
const N = BW * BH;
const BWX = BW + 2;                             // 1-cell apron each side for the x second difference
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH;
  S.L = new Float64Array(BWX * BH); S.DOM = new Int16Array(BWX * BH); S.MRG = new Float32Array(BWX * BH);
}

const sd = P.seed | 0;
function hsh(ix, iy) {
  let h = (Math.imul(ix, 374761393) + Math.imul(iy, 668265263) + Math.imul(sd, 1442695041)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177) | 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;   // >>> not >> : an arithmetic fold caps the hash at 0.5
}

const tt = K.t;
const nP = Math.max(4, Math.min(8, 4 + Math.round(P.density * 4)));   // phases -> up to nP-1 solitons

// ---- the k_i must stay strictly increasing (that is what keeps tau positive). Build them as
// a sorted ladder of seeded gaps, each gap breathing on its own incommensurate rate: the
// soliton amplitudes ((k_j-k_i)^2/2) and directions therefore never repeat. ----
const spr = 0.45 + P.spread * 1.5;
const ks = new Float64Array(nP), ts = new Float64Array(nP);
{
  let acc = 0;
  for (let i = 0; i < nP; i++) {
    const g0 = 0.45 + hsh(i * 3 + 1, 7) * 0.9;
    const wob = 0.34 * Math.sin(tt * (0.031 + hsh(i * 3 + 2, 9) * 0.05) + hsh(i * 3 + 3, 11) * 6.28)
              + 0.16 * Math.sin(tt * (0.071 + hsh(i, 13) * 0.04) + i * 1.7);
    const gap = Math.max(0.14, g0 * (1 + wob));
    ks[i] = acc; acc += gap;
  }
  const mid = ks[nP - 1] * 0.5;
  for (let i = 0; i < nP; i++) ks[i] = (ks[i] - mid) * (spr / Math.max(0.4, ks[nP - 1] * 0.5)) * 0.9;
  // t_i: the second Vandermonde row, also strictly increasing -> Plucker coords all positive
  let a2 = 0;
  for (let i = 0; i < nP; i++) {
    ts[i] = a2;
    a2 += 0.3 + hsh(i * 5 + 2, 17) * 1.2 * (1 + 0.4 * Math.sin(tt * (0.043 + i * 0.011) + i * 2.3));
  }
}

// evolution time: bounded (a linear t would sail the web off-frame), built from
// incommensurate sines so the junctions migrate forever without ever repeating
const sp = 0.3 + P.speed * 0.9;
const ev = 1.15 * Math.sin(tt * 0.067 * sp) + 0.62 * Math.sin(tt * 0.149 * sp + 1.9) + 0.31 * Math.sin(tt * 0.0311 * sp + 0.4);

// world window: x across, y down
const XS = 15.5 / Math.max(0.35, P.scale * 0.85);
const YS = XS * BH / BW;
const x0w = -XS + (P.x - 0.5) * XS * 1.4, y0w = -YS + (P.y - 0.5) * YS * 1.4;
const dxw = (2 * XS) / BW, dyw = (2 * YS) / BH;

// precompute pair coefficients log(c_ij) = log((t_j-t_i)(k_j-k_i))
const nPair = (nP * (nP - 1)) >> 1;
if (!S.qi || S.qi.length !== nPair) { S.qi = new Int16Array(nPair); S.qj = new Int16Array(nPair); S.lc = new Float64Array(nPair); }
const QI = S.qi, QJ = S.qj, LC = S.lc;
{
  let n = 0;
  for (let i = 0; i < nP; i++) for (let j = i + 1; j < nP; j++) {
    QI[n] = i; QJ[n] = j;
    LC[n] = Math.log(Math.max(1e-9, (ts[j] - ts[i]) * (ks[j] - ks[i])));
    n++;
  }
}
// theta_i = k x + k^2 y + k^3 t  -> per-pair: a*x + b*y + c
const PA = new Float64Array(nPair), PB = new Float64Array(nPair), PC = new Float64Array(nPair);
for (let n = 0; n < nPair; n++) {
  const i = QI[n], j = QJ[n];
  PA[n] = ks[i] + ks[j];
  PB[n] = ks[i] * ks[i] + ks[j] * ks[j];
  PC[n] = (ks[i] * ks[i] * ks[i] + ks[j] * ks[j] * ks[j]) * ev + LC[n];
}

// ---- L = log tau on a (BW+2) x BH grid, via a stable log-sum-exp; DOM = the dominant pair
// (the asymptotic plane-wave region this pixel sits in), MRG = how far it dominates by. ----
const L = S.L, DOM = S.DOM, MRG = S.MRG;
for (let j = 0; j < BH; j++) {
  const yw = y0w + j * dyw;
  const row = j * BWX;
  for (let ii = 0; ii < BWX; ii++) {
    const xw = x0w + (ii - 1) * dxw;
    let m = -1e300, best = 0, second = -1e300;
    for (let n = 0; n < nPair; n++) {
      const e = PA[n] * xw + PB[n] * yw + PC[n];
      if (e > m) { second = m; m = e; best = n; } else if (e > second) second = e;
    }
    let s = 0;
    for (let n = 0; n < nPair; n++) {
      const d = PA[n] * xw + PB[n] * yw + PC[n] - m;
      if (d > -34) s += Math.exp(d);            // terms below this contribute < 1e-14
    }
    L[row + ii] = m + Math.log(s);
    DOM[row + ii] = best;
    MRG[row + ii] = m - second;
  }
}

// ---- render ----
const g = S.g; g.loadPixels(); const px = g.pixels;
const sec = K.section | 0;
const style = P.style;
const hb = ((P.hue + sec * 16 + Math.sin(tt * 0.0177) * 18) % 360 + 360) % 360;
const gain = 0.5 + P.energy * 1.35 + A.rms * 0.4;
const cellAmt = P.cells;
const ih2 = 1 / (dxw * dxw);
function pal(m, spx, off) {
  const hr = hb / 360 + off;
  return [0.5 + 0.5 * Math.cos(6.2831 * (m + hr)),
          0.5 + 0.5 * Math.cos(6.2831 * (m + hr + spx)),
          0.5 + 0.5 * Math.cos(6.2831 * (m + hr + spx * 2))];
}
const inp = 1 / Math.max(1, nPair - 1);
for (let j = 0; j < BH; j++) {
  const row = j * BWX;
  for (let i = 0; i < BW; i++) {
    const ii = i + 1;
    // u = 2 * d2/dx2 log tau  -> the soliton ridges
    const u = 2 * (L[row + ii + 1] - 2 * L[row + ii] + L[row + ii - 1]) * ih2;
    const ridge = Math.max(0, Math.min(1, u * 0.85 * gain));
    const dm = DOM[row + ii];
    // the cells between ridges are the asymptotic plane-wave regions — tinting them is what
    // keeps the frame from being "a few bright lines on black" (the classic luminance fail)
    const cellHue = ((dm * 0.163 + hsh(dm + 3, 23) * 0.28) % 1 + 1) % 1;
    const soft = Math.exp(-MRG[row + ii] * 0.22);   // smooth falloff away from every seam
    let r, gg, b;
    if (style === 'tropical') {          // the mathematician's read: flat cells, hard black curves
      const c = pal(cellHue, 0.33, 0.0);
      const fl = 0.42 + 0.5 * cellAmt;
      const ln = Math.min(1, Math.pow(ridge, 0.55) * 1.6);
      r = Math.min(1, c[0] * fl * (1 - ln * 0.95)); gg = Math.min(1, c[1] * fl * (1 - ln * 0.95)); b = Math.min(1, c[2] * fl * (1 - ln * 0.95));
    } else if (style === 'interferogram') {  // fringes keyed to the tau potential — abstracted
      const fr = 0.5 + 0.5 * Math.cos(L[row + ii] * (0.9 + P.energy * 3.4));
      const v = 0.14 + fr * 0.62 + ridge * 0.4;
      r = Math.min(1, v * 0.9); gg = Math.min(1, v * 0.99); b = Math.min(1, v * 0.84);
    } else if (style === 'thermal') {
      const m = Math.min(1, (ridge * 0.72 + soft * 0.22 * cellAmt + 0.06) * (0.55 + P.energy * 0.8));
      r = Math.min(1, m * 2.15); gg = Math.min(1, Math.max(0, m * 2.0 - 0.55)); b = Math.min(1, Math.max(0, m * 3.1 - 2.05) + Math.max(0, 0.4 - m * 1.5));
    } else if (style === 'ink') {        // sumi: pale paper, ridges as dark brush with bleed
      const bleed = soft * 0.30 * cellAmt;
      const ink = Math.min(1, Math.pow(ridge, 0.8) * (0.6 + gain * 0.5) + bleed * 0.55);
      const paper = 0.95 - ink * 0.87;
      r = paper * 0.99; gg = paper * 0.96; b = paper * 0.89;
    } else {                             // shallow_water (default) — sunlit lagoon, foam crests
      const c = pal(0.5 + cellHue * 0.16, 0.15, 0.0);
      const base = (0.15 + soft * 0.30 * cellAmt) * (0.7 + gain * 0.4);
      const foam = Math.pow(ridge, 0.9) * gain * 0.85;
      r = Math.min(1, c[0] * base + foam * 0.95 + foam * foam * 0.25);
      gg = Math.min(1, c[1] * base + foam * 0.97 + foam * foam * 0.22);
      b = Math.min(1, c[2] * base * 1.15 + foam * 1.0 + foam * foam * 0.2);
    }
    const o = 4 * (j * BW + i);
    px[o] = Math.max(0, Math.min(255, r * 255));
    px[o + 1] = Math.max(0, Math.min(255, gg * 255));
    px[o + 2] = Math.max(0, Math.min(255, b * 255));
    px[o + 3] = 255;
  }
}
g.updatePixels();

push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
